static int cmp(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int* sortLog(int* times, int timesSize, int k, int* returnSize) {
    int* a = malloc(timesSize * sizeof(int));
    memcpy(a, times, timesSize * sizeof(int));
    qsort(a, timesSize, sizeof(int), cmp);
    *returnSize = timesSize;
    return a;
}

