import heapq

class Solution:
    def sortLog(self, times: List[int], k: int) -> List[int]:
        heap, out = [], []
        for t in times:
            heapq.heappush(heap, t)
            if len(heap) > k:
                out.append(heapq.heappop(heap))
        while heap:
            out.append(heapq.heappop(heap))
        return out

