class Solution {
    public int[] sortLog(int[] times, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        int[] out = new int[times.length];
        int w = 0;
        for (int t : times) {
            heap.add(t);
            if (heap.size() > k) out[w++] = heap.poll();
        }
        while (!heap.isEmpty()) out[w++] = heap.poll();
        return out;
    }
}

