class Solution {
public:
    vector<int> sortLog(vector<int>& times, int k) {
        priority_queue<int, vector<int>, greater<int>> heap;
        vector<int> out;
        for (int t : times) {
            heap.push(t);
            if ((int) heap.size() > k) { out.push_back(heap.top()); heap.pop(); }
        }
        while (!heap.empty()) { out.push_back(heap.top()); heap.pop(); }
        return out;
    }
};

code.c:
static void push(int* h, int* n, int x) {
    int i = (*n)++;
    while (i > 0 && h[(i - 1) / 2] > x) { h[i] = h[(i - 1) / 2]; i = (i - 1) / 2; }
    h[i] = x;
}

static int pop(int* h, int* n) {
    int top = h[0], x = h[--(*n)], i = 0;
    for (int c = 1; c < *n; i = c, c = 2 * c + 1) {
        if (c + 1 < *n && h[c + 1] < h[c]) c++;
        if (h[c] >= x) break;
        h[i] = h[c];
    }
    if (*n > 0) h[i] = x;
    return top;
}

int* sortLog(int* times, int timesSize, int k, int* returnSize) {
    int* heap = malloc((k + 2) * sizeof(int));
    int* out = malloc(timesSize * sizeof(int));
    int n = 0, w = 0;
    for (int i = 0; i < timesSize; i++) {
        push(heap, &n, times[i]);
        if (n > k) out[w++] = pop(heap, &n);
    }
    while (n > 0) out[w++] = pop(heap, &n);
    free(heap);
    *returnSize = timesSize;
    return out;
}
